(function(root){
'use strict';
const BASE=new URL('.',document.currentScript.src),INDEX='givemefive-offline-index',META=new URL('__offline_manifest__',BASE).href,READY=new URL('__offline_ready__',BASE).href;
let manifest,name,flight=new Map(),downloadJob=null;
root.PathlineTextbook={course:{topics:[],units:[]},readings:[],exercises:[],assets:[],supplements:[],reviews:[],objects:[],figures:[]};
const url=path=>new URL(path,BASE).href;
async function valid(response,path){if(!response?.ok)return false;const rule=manifest.resources[path];if(!rule)return false;const bytes=await response.clone().arrayBuffer();if(bytes.byteLength!==rule.bytes)return false;const digest=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(digest),v=>v.toString(16).padStart(2,'0')).join('')===rule.sha256;}
async function read(path){const cache=await caches.open(name),local=await cache.match(url(path));if(local&&await valid(local,path))return local.json();const r=await fetch(url(path),{cache:'no-store'});if(!await valid(r,path))throw Error('Resource verification failed: '+path);return r.json();}
async function init(){const index=await caches.open(INDEX);try{const r=await fetch(url('data/runtime-manifest.json'),{cache:'no-store'});if(!r.ok)throw Error('Manifest unavailable');const next=await r.json();if(!next.resource_version||!next.resources)throw Error('Manifest needs rebuilding');manifest=next;}catch(error){const saved=await index.match(META);if(!saved)throw error;manifest=await saved.json();}
name='givemefive-course-'+manifest.course_id+'-'+manifest.resource_version;
// Store the full version snapshot, never mix old course resources with a new shell.
await index.put(META,new Response(JSON.stringify(manifest),{headers:{'Content-Type':'application/json'}}));
root.PathlineTextbook.course=await read('data/course.json');}
const ids={readings:'content_id',exercises:'exercise_id',assets:'asset_id',supplements:'supplement_id',reviews:'chapter',objects:'object_id',figures:'figure_id'};
async function ensureTopic(id){if(!manifest.topics[id])return;const key=manifest.resource_version+':'+id;if(flight.has(key))return flight.get(key);const p=read(manifest.topics[id].path).then(bundle=>{for(const [k,field] of Object.entries(ids)){const map=new Map(root.PathlineTextbook[k].map(v=>[v[field],v]));for(const v of bundle[k])map.set(v[field],v);root.PathlineTextbook[k]=[...map.values()];}}).catch(e=>{flight.delete(key);throw e;});flight.set(key,p);return p;}
async function ensure(){for(const id of Object.keys(manifest.topics))await ensureTopic(id);}
function pathsFor(unit=null){const topics=unit===null?Object.keys(manifest.topics):manifest.units[String(unit)];if(!topics)throw Error('Unknown unit');return [...new Set([...manifest.shell,'data/course.json','data/source-metadata.json',...topics.flatMap(id=>[manifest.topics[id].path,...manifest.topics[id].assets])])];}
async function status(unit=null){const paths=pathsFor(unit),cache=await caches.open(name);let verified=0;for(let i=0;i<paths.length;i+=4)await Promise.all(paths.slice(i,i+4).map(async path=>{if(await valid(await cache.match(url(path)),path))verified++;}));return {verified,total:paths.length,complete:verified===paths.length,version:manifest.resource_version};}
async function transfer(paths,onProgress,signal){const cache=await caches.open(name),prior=await Promise.all((await caches.keys()).filter(key=>key!==name&&key.startsWith('givemefive-course-'+manifest.course_id+'-')).map(key=>caches.open(key)));let done=0,failed=[];for(let i=0;i<paths.length;i+=4){if(signal.aborted)throw new DOMException('Download paused','AbortError');await Promise.all(paths.slice(i,i+4).map(async path=>{try{if(!await valid(await cache.match(url(path)),path)){let r;for(const old of prior){const candidate=await old.match(url(path));if(await valid(candidate,path)){r=candidate;break;}}if(!r)r=await fetch(url(path),{cache:'no-store',signal});if(!await valid(r,path))throw Error('Resource verification failed');await cache.put(url(path),r);}done++;}catch(error){if(error.name==='AbortError')return;failed.push(path);}onProgress?.(done,paths.length,{failed:failed.length});}));}if(signal.aborted)throw new DOMException('Download paused','AbortError');if(failed.length){const error=Error('Download incomplete: '+failed.join(', '));error.failed=failed;throw error;}}
async function download(onProgress,unit=null){if(downloadJob)throw Error('A download is already running');const job=new AbortController();downloadJob=job;try{await transfer(pathsFor(unit),onProgress,job.signal);const result=await status(unit);if(result.complete)await (await caches.open(INDEX)).put(READY,new Response(JSON.stringify(manifest),{headers:{'Content-Type':'application/json'}}));return result;}finally{downloadJob=null;}}
function pause(){downloadJob?.abort();}
// This exports a real PDF file; it is deliberately separate from browser offline caching.
async function downloadPDF(onProgress){if(downloadJob)throw Error('A download is already running');const job=new AbortController();downloadJob=job;try{const response=await fetch(url('source/pdf-parts.json'),{cache:'no-store',signal:job.signal});const pdf=await response.json(),cache=await caches.open(name),parts=[];let done=0;for(const part of pdf.parts){const path='source/'+part.path;let r=await cache.match(url(path));if(!await valid(r,path))r=await fetch(url(path),{cache:'no-store',signal:job.signal});if(!await valid(r,path))throw Error('PDF verification failed: '+path);parts.push(await r.arrayBuffer());onProgress?.(++done,pdf.parts.length);}const blob=new Blob(parts,{type:'application/pdf'});if(blob.size!==pdf.bytes)throw Error('PDF size mismatch');const digest=await crypto.subtle.digest('SHA-256',await blob.arrayBuffer()),sha=Array.from(new Uint8Array(digest),v=>v.toString(16).padStart(2,'0')).join('');if(sha!==pdf.sha256)throw Error('PDF checksum mismatch');const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='OpenStax-University-Physics-Volume-1.pdf';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),30000);}finally{downloadJob=null;}}
async function remove(){if(downloadJob)throw Error('Pause the download first');const prefix='givemefive-course-'+manifest.course_id+'-';for(const key of await caches.keys())if(key.startsWith(prefix))await caches.delete(key);if(manifest.course_id==='ap-physics-c-mechanics-2026-27')await caches.delete('givemefive-course-ap-v1');const index=await caches.open(INDEX);await index.delete(META);await index.delete(READY);flight.clear();}
root.ContentRuntime={init,ensure,ensureTopic,download,downloadPDF,remove,pause,status,downloaded:async unit=>(await status(unit)).complete,get cacheName(){return name;},get manifest(){return manifest;}};
})(window);
